parameters.jsCode:
const raw = $input.first().json.content[0].text;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { score: 0, categoria: 'Error', justificacion: 'No se pudo parsear la respuesta del modelo.' };
}
return [{ json: parsed }];

